CREATE OR REPLACE FUNCTION create_execute_query_script() RETURNS void AS $$
BEGIN
    EXECUTE 'CREATE OR REPLACE FUNCTION run_user_query(query_file_path TEXT) RETURNS void AS $$
    import sys
    from run_db import run_query

    def run_user_query(query_file_path):
        try:
            with open(query_file_path, 'r') as file:
                query = file.read()
            run_query(query)
        except Exception as e:
            print(f'Error: {e}')
            sys.exit(1)

    if __name__ == "__main__":
        if len(sys.argv) < 2:
            print('Usage: python execute_query.py <QUERY_FILE_PATH>')
            sys.exit(1)
        run_user_query(sys.argv[1])
    $$ LANGUAGE plpgsql;';
END;
$$ LANGUAGE plpgsql;

